(function(root){'use strict';
const normalize=value=>String(value??'').normalize('NFKC').toLocaleLowerCase('ru-RU').replace(/ё/g,'е').replace(/[^\p{L}\p{N}]+/gu,' ').trim();
function near(a,b){if(a===b)return true;if(Math.abs(a.length-b.length)>1)return false;if(a.length===b.length){const differences=[];for(let i=0;i<a.length;i++)if(a[i]!==b[i])differences.push(i);return differences.length===1||differences.length===2&&differences[1]===differences[0]+1&&a[differences[0]]===b[differences[1]]&&a[differences[1]]===b[differences[0]];}if(a.length>b.length)[a,b]=[b,a];let i=0,j=0,skipped=false;while(i<a.length&&j<b.length){if(a[i]===b[j]){i++;j++;}else{if(skipped)return false;skipped=true;j++;}}return true;}
function search(records,query){const q=normalize(query),tokens=q.split(' ').filter(Boolean);if(!tokens.length)return records.map((r,i)=>({...r,score:0,nameOrder:i}));const hits=[];records.forEach((r,i)=>{const label=normalize(r.label),words=label.split(' '),aliases=normalize(r.aliases).split(' '),context=normalize(r.hint).split(' ');let score=label===q?0:label.startsWith(q)?1:2;for(const token of tokens){if(words.some(w=>w.startsWith(token)))continue;if(aliases.some(w=>w.startsWith(token))){score+=3;continue;}if(context.some(w=>w.startsWith(token))){score+=6;continue;}if(token.length>=4&&[...words,...aliases].some(w=>near(token,w))){score+=10;continue;}return;}hits.push({...r,score,nameOrder:i});});return hits.sort((a,b)=>a.score-b.score||a.nameOrder-b.nameOrder);}
const api={normalize,search};if(typeof module!=='undefined'&&module.exports)module.exports=api;else root.SettingsSearchModel=api;
})(typeof window!=='undefined'?window:globalThis);
